from __future__ import annotations

import json
import os
from dataclasses import dataclass
from pathlib import Path
import shutil
import tempfile
from typing import Iterable, Iterator


MAX_ENTRIES_PER_DIRECTORY = 30
MAX_FILE_SIZE = 15_000_000
IO_BLOCK_SIZE = 1024 * 1024
MANIFEST_DIRECTORY = "manifest"
PAYLOAD_DIRECTORY = "payload"
MANIFEST_PART_PREFIX = "manifest-part"
PAYLOAD_PART_PREFIX = "payload-part"
FORMAT_NAME = "directory-reshard"
FORMAT_VERSION = 1


class ReshardError(Exception):
    """Raised when a source tree or resharded tree is not usable."""


@dataclass(frozen=True)
class Entry:
    kind: str
    parts: tuple[str, ...]
    size: int = 0
    first_chunk: int | None = None
    chunk_count: int = 0


def _tree_width(item_count: int) -> int:
    if item_count <= 0:
        raise ValueError("item_count must be positive")

    width = 0
    capacity = MAX_ENTRIES_PER_DIRECTORY
    while item_count > capacity:
        width += 1
        capacity *= MAX_ENTRIES_PER_DIRECTORY
    return width + 1 if width else 0


def tree_relative_path(
    index: int,
    item_count: int,
    prefix: str,
    suffix: str,
) -> Path:
    """Return a path whose directory tree has at most 30 children per directory."""
    if item_count <= 0 or index < 0 or index >= item_count:
        raise ValueError("index is outside the item count")

    width = _tree_width(item_count)
    if width == 0:
        return Path(f"{prefix}-00{suffix}") if index == 0 else Path(
            f"{prefix}-{index:02d}{suffix}"
        )

    digits = [0] * width
    remainder = index
    for position in range(width - 1, -1, -1):
        digits[position] = remainder % MAX_ENTRIES_PER_DIRECTORY
        remainder //= MAX_ENTRIES_PER_DIRECTORY

    directories = [f"{prefix}-{digit:02d}" for digit in digits[:-1]]
    filename = f"{prefix}-{digits[-1]:02d}{suffix}"
    return Path(*directories, filename)


def _scan_directory(
    directory: Path,
    parent_parts: tuple[str, ...],
    entries: list[Entry],
    next_chunk: int,
) -> int:
    try:
        children = sorted(os.scandir(directory), key=lambda item: item.name)
    except OSError as exc:
        raise ReshardError(f"cannot read {directory}: {exc}") from exc

    try:
        for child in children:
            relative_parts = parent_parts + (child.name,)
            try:
                if child.is_symlink():
                    raise ReshardError(
                        f"symbolic links are not supported: {directory / child.name}"
                    )
                if child.is_dir(follow_symlinks=False):
                    entries.append(Entry("dir", relative_parts))
                    next_chunk = _scan_directory(
                        Path(child.path), relative_parts, entries, next_chunk
                    )
                elif child.is_file(follow_symlinks=False):
                    size = child.stat(follow_symlinks=False).st_size
                    chunk_count = (size + MAX_FILE_SIZE - 1) // MAX_FILE_SIZE
                    first_chunk = next_chunk if chunk_count else None
                    entries.append(
                        Entry(
                            "file",
                            relative_parts,
                            size=size,
                            first_chunk=first_chunk,
                            chunk_count=chunk_count,
                        )
                    )
                    next_chunk += chunk_count
                else:
                    raise ReshardError(
                        f"unsupported filesystem entry: {directory / child.name}"
                    )
            except OSError as exc:
                raise ReshardError(f"cannot inspect {directory / child.name}: {exc}") from exc
    finally:
        for child in children:
            child.close()

    return next_chunk


def scan_source_tree(source: Path) -> tuple[list[Entry], int]:
    entries: list[Entry] = []
    total_chunks = _scan_directory(source, (), entries, 0)
    return entries, total_chunks


def _json_line(value: dict[str, object]) -> bytes:
    return (
        json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False).encode(
            "utf-8"
        )
        + b"\n"
    )


def iter_manifest_lines(
    entries: Iterable[Entry], total_chunks: int
) -> Iterator[bytes]:
    yield _json_line(
        {
            "type": "header",
            "format": FORMAT_NAME,
            "version": FORMAT_VERSION,
            "payload_chunks": total_chunks,
        }
    )
    for entry in entries:
        record: dict[str, object] = {
            "type": entry.kind,
            "path": list(entry.parts),
        }
        if entry.kind == "file":
            record.update(
                {
                    "size": entry.size,
                    "first_chunk": entry.first_chunk,
                    "chunk_count": entry.chunk_count,
                }
            )
        yield _json_line(record)


def manifest_chunk_count(lines: Iterable[bytes]) -> int:
    count = 1
    current_size = 0
    for line in lines:
        if len(line) > MAX_FILE_SIZE:
            raise ReshardError("a manifest record exceeds the 15 MB file limit")
        if current_size and current_size + len(line) > MAX_FILE_SIZE:
            count += 1
            current_size = 0
        current_size += len(line)
    return count


def write_manifest(
    manifest_directory: Path,
    entries: list[Entry],
    total_chunks: int,
) -> None:
    lines = iter_manifest_lines(entries, total_chunks)
    part_count = manifest_chunk_count(iter_manifest_lines(entries, total_chunks))
    manifest_directory.mkdir()

    part_index = 0
    part_size = 0
    handle = None
    try:
        for line in lines:
            if handle is None or part_size and part_size + len(line) > MAX_FILE_SIZE:
                if handle is not None:
                    handle.close()
                relative = tree_relative_path(
                    part_index,
                    part_count,
                    MANIFEST_PART_PREFIX,
                    ".jsonl",
                )
                part_path = manifest_directory / relative
                part_path.parent.mkdir(parents=True, exist_ok=True)
                handle = part_path.open("wb")
                part_index += 1
                part_size = 0
            handle.write(line)
            part_size += len(line)
    finally:
        if handle is not None:
            handle.close()

    if part_index != part_count:
        raise ReshardError("manifest generation produced an unexpected number of parts")


def _read_exact(source, size: int) -> bytes:
    pieces: list[bytes] = []
    remaining = size
    while remaining:
        piece = source.read(min(IO_BLOCK_SIZE, remaining))
        if not piece:
            break
        pieces.append(piece)
        remaining -= len(piece)
    return b"".join(pieces)


def write_payload(
    source: Path,
    payload_directory: Path,
    entries: Iterable[Entry],
    total_chunks: int,
) -> None:
    payload_directory.mkdir()
    if total_chunks == 0:
        return

    for entry in entries:
        if entry.kind != "file" or entry.chunk_count == 0:
            continue

        source_path = source.joinpath(*entry.parts)
        try:
            source_handle = source_path.open("rb")
        except OSError as exc:
            raise ReshardError(f"cannot open {source_path}: {exc}") from exc

        try:
            remaining = entry.size
            for chunk_offset in range(entry.chunk_count):
                expected_size = min(MAX_FILE_SIZE, remaining)
                relative = tree_relative_path(
                    entry.first_chunk + chunk_offset,  # type: ignore[operator]
                    total_chunks,
                    PAYLOAD_PART_PREFIX,
                    ".bin",
                )
                destination = payload_directory / relative
                destination.parent.mkdir(parents=True, exist_ok=True)
                try:
                    with destination.open("wb") as destination_handle:
                        bytes_written = 0
                        while bytes_written < expected_size:
                            piece = source_handle.read(
                                min(IO_BLOCK_SIZE, expected_size - bytes_written)
                            )
                            if not piece:
                                raise ReshardError(
                                    f"{source_path} changed while it was being copied"
                                )
                            destination_handle.write(piece)
                            bytes_written += len(piece)
                except OSError as exc:
                    raise ReshardError(f"cannot write {destination}: {exc}") from exc
                remaining -= expected_size

            if source_handle.read(1):
                raise ReshardError(f"{source_path} changed while it was being copied")
        except OSError as exc:
            raise ReshardError(f"cannot read {source_path}: {exc}") from exc
        finally:
            source_handle.close()


def _path_is_within(path: Path, parent: Path) -> bool:
    try:
        path.relative_to(parent)
    except ValueError:
        return False
    return True


def _validate_compress_paths(source: Path, output: Path) -> tuple[Path, Path]:
    try:
        source_resolved = source.resolve(strict=True)
    except OSError as exc:
        raise ReshardError(f"cannot resolve input directory {source}: {exc}") from exc
    if not source_resolved.is_dir():
        raise ReshardError(f"input is not a directory: {source}")

    output_resolved = output.resolve(strict=False)
    if source_resolved == output_resolved or _path_is_within(output_resolved, source_resolved):
        raise ReshardError("output directory must not be the input directory or its child")

    if output.exists():
        if output.is_symlink() or not output.is_dir():
            raise ReshardError(f"output is not a directory: {output}")
        try:
            next(output.iterdir())
        except StopIteration:
            pass
        except OSError as exc:
            raise ReshardError(f"cannot inspect output directory {output}: {exc}") from exc
        else:
            raise ReshardError(f"output directory is not empty: {output}")

    return source_resolved, output_resolved


def compress_directory(input_dir: str | os.PathLike[str], output_dir: str | os.PathLike[str]) -> None:
    source, output = _validate_compress_paths(Path(input_dir), Path(output_dir))
    entries, total_chunks = scan_source_tree(source)

    try:
        output.parent.mkdir(parents=True, exist_ok=True)
        staging = Path(
            tempfile.mkdtemp(prefix=f".{output.name}.tmp-", dir=str(output.parent))
        )
    except OSError as exc:
        raise ReshardError(f"cannot create temporary output directory: {exc}") from exc

    keep_staging = True
    try:
        write_manifest(staging / MANIFEST_DIRECTORY, entries, total_chunks)
        write_payload(source, staging / PAYLOAD_DIRECTORY, entries, total_chunks)

        if output.exists():
            try:
                output.rmdir()
            except OSError as exc:
                raise ReshardError(f"output directory changed or is no longer empty: {exc}") from exc
        os.replace(staging, output)
        keep_staging = False
    finally:
        if keep_staging:
            shutil.rmtree(staging, ignore_errors=True)


def _walk_entries(root: Path) -> Iterator[tuple[Path, bool, int]]:
    """Yield (path, is_directory, file_size) without following symlinks."""
    try:
        children = sorted(os.scandir(root), key=lambda item: item.name)
    except OSError as exc:
        raise ReshardError(f"cannot read {root}: {exc}") from exc

    try:
        if len(children) > MAX_ENTRIES_PER_DIRECTORY:
            raise ReshardError(f"directory exceeds the {MAX_ENTRIES_PER_DIRECTORY}-entry limit: {root}")
        for child in children:
            path = Path(child.path)
            try:
                if child.is_symlink():
                    raise ReshardError(f"symbolic links are not supported: {path}")
                if child.is_dir(follow_symlinks=False):
                    yield path, True, 0
                    yield from _walk_entries(path)
                elif child.is_file(follow_symlinks=False):
                    size = child.stat(follow_symlinks=False).st_size
                    if size > MAX_FILE_SIZE:
                        raise ReshardError(f"file exceeds the 15 MB limit: {path}")
                    yield path, False, size
                else:
                    raise ReshardError(f"unsupported filesystem entry: {path}")
            except OSError as exc:
                raise ReshardError(f"cannot inspect {path}: {exc}") from exc
    finally:
        for child in children:
            child.close()


def validate_resharded_layout(root: Path) -> tuple[Path, Path]:
    try:
        root_entries = sorted(os.scandir(root), key=lambda item: item.name)
    except OSError as exc:
        raise ReshardError(f"cannot read resharded directory {root}: {exc}") from exc

    try:
        if len(root_entries) > MAX_ENTRIES_PER_DIRECTORY:
            raise ReshardError(f"directory exceeds the {MAX_ENTRIES_PER_DIRECTORY}-entry limit: {root}")
        names = {entry.name for entry in root_entries}
        expected = {MANIFEST_DIRECTORY, PAYLOAD_DIRECTORY}
        if names != expected or len(root_entries) != len(expected):
            raise ReshardError(
                f"expected only '{MANIFEST_DIRECTORY}' and '{PAYLOAD_DIRECTORY}' in {root}"
            )
        for entry in root_entries:
            if entry.is_symlink() or not entry.is_dir(follow_symlinks=False):
                raise ReshardError(f"expected a directory: {root / entry.name}")
    finally:
        for entry in root_entries:
            entry.close()

    manifest = root / MANIFEST_DIRECTORY
    payload = root / PAYLOAD_DIRECTORY
    list(_walk_entries(manifest))
    list(_walk_entries(payload))
    return manifest, payload


def _collect_regular_files(root: Path) -> list[Path]:
    files: list[Path] = []

    def collect(directory: Path) -> None:
        try:
            children = sorted(os.scandir(directory), key=lambda item: item.name)
        except OSError as exc:
            raise ReshardError(f"cannot read {directory}: {exc}") from exc
        try:
            for child in children:
                path = Path(child.path)
                if child.is_symlink():
                    raise ReshardError(f"symbolic links are not supported: {path}")
                if child.is_dir(follow_symlinks=False):
                    collect(path)
                elif child.is_file(follow_symlinks=False):
                    files.append(path)
                else:
                    raise ReshardError(f"unsupported filesystem entry: {path}")
        finally:
            for child in children:
                child.close()

    collect(root)
    files.sort(key=lambda path: path.relative_to(root).parts)
    return files


def _manifest_parts(path: Path, manifest: Path) -> tuple[str, ...]:
    return path.relative_to(manifest).parts


def _safe_parts(value: object) -> tuple[str, ...]:
    if not isinstance(value, list) or not value or not all(
        isinstance(part, str) for part in value
    ):
        raise ReshardError("manifest contains an invalid path")
    parts = tuple(value)
    for part in parts:
        if not part or part in {".", ".."} or "/" in part or "\x00" in part:
            raise ReshardError("manifest contains an unsafe path")
    return parts


def _read_json_line(raw: bytes, path: Path) -> dict[str, object]:
    if not raw.endswith(b"\n"):
        raise ReshardError(f"manifest part does not end with a newline: {path}")
    try:
        value = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ReshardError(f"invalid manifest record in {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise ReshardError(f"manifest record is not an object: {path}")
    return value


def _copy_restored_file(
    payload: Path,
    destination: Path,
    size: int,
    first_chunk: int | None,
    chunk_count: int,
    total_chunks: int,
) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    try:
        with destination.open("wb") as destination_handle:
            remaining = size
            for offset in range(chunk_count):
                chunk_index = first_chunk + offset  # type: ignore[operator]
                relative = tree_relative_path(
                    chunk_index,
                    total_chunks,
                    PAYLOAD_PART_PREFIX,
                    ".bin",
                )
                chunk_path = payload / relative
                if chunk_path.is_symlink() or not chunk_path.is_file():
                    raise ReshardError(f"missing payload chunk: {chunk_path}")
                chunk_size = chunk_path.stat().st_size
                expected_size = min(MAX_FILE_SIZE, remaining)
                if chunk_size != expected_size:
                    raise ReshardError(
                        f"payload chunk has size {chunk_size}, expected {expected_size}: {chunk_path}"
                    )
                try:
                    with chunk_path.open("rb") as chunk_handle:
                        copied = 0
                        while copied < expected_size:
                            piece = chunk_handle.read(min(IO_BLOCK_SIZE, expected_size - copied))
                            if not piece:
                                raise ReshardError(f"payload chunk ended early: {chunk_path}")
                            destination_handle.write(piece)
                            copied += len(piece)
                except OSError as exc:
                    raise ReshardError(f"cannot read payload chunk {chunk_path}: {exc}") from exc
                remaining -= expected_size
            if remaining != 0:
                raise ReshardError(f"file record has an incorrect chunk count: {destination}")
    except OSError as exc:
        raise ReshardError(f"cannot write restored file {destination}: {exc}") from exc


def _reconstruct_into(
    root: Path,
    manifest: Path,
    payload: Path,
    destination_root: Path,
) -> None:
    manifest_files = _collect_regular_files(manifest)
    if not manifest_files:
        raise ReshardError("manifest is empty")

    manifest_part_count = len(manifest_files)
    for index, path in enumerate(manifest_files):
        expected = manifest / tree_relative_path(
            index,
            manifest_part_count,
            MANIFEST_PART_PREFIX,
            ".jsonl",
        )
        if path != expected:
            raise ReshardError(f"unexpected manifest part: {path}")

    payload_files = _collect_regular_files(payload)
    payload_file_sizes = [path.stat().st_size for path in payload_files]
    if any(size > MAX_FILE_SIZE for size in payload_file_sizes):
        raise ReshardError("payload contains a file exceeding the 15 MB limit")

    header: dict[str, object] | None = None
    total_chunks: int | None = None
    seen: dict[tuple[str, ...], str] = {}
    next_chunk = 0

    for manifest_path in manifest_files:
        try:
            handle = manifest_path.open("rb")
        except OSError as exc:
            raise ReshardError(f"cannot read manifest part {manifest_path}: {exc}") from exc
        try:
            for raw in handle:
                record = _read_json_line(raw, manifest_path)
                if header is None:
                    if record.get("type") != "header":
                        raise ReshardError("manifest does not begin with a header")
                    if record.get("format") != FORMAT_NAME or record.get("version") != FORMAT_VERSION:
                        raise ReshardError("unsupported resharded directory format")
                    candidate = record.get("payload_chunks")
                    if isinstance(candidate, bool) or not isinstance(candidate, int) or candidate < 0:
                        raise ReshardError("manifest header has an invalid payload chunk count")
                    header = record
                    total_chunks = candidate
                    if len(payload_files) != total_chunks:
                        raise ReshardError(
                            f"manifest expects {total_chunks} payload chunks, found {len(payload_files)}"
                        )
                    continue

                record_type = record.get("type")
                if record_type not in {"dir", "file"}:
                    raise ReshardError("manifest contains an invalid entry type")
                parts = _safe_parts(record.get("path"))
                if parts in seen:
                    raise ReshardError(f"manifest contains a duplicate path: {'/'.join(parts)}")
                for parent_index in range(1, len(parts)):
                    parent = parts[:parent_index]
                    if seen.get(parent) == "file":
                        raise ReshardError("manifest contains a file with children")
                seen[parts] = record_type
                destination = destination_root.joinpath(*parts)

                if record_type == "dir":
                    destination.parent.mkdir(parents=True, exist_ok=True)
                    try:
                        destination.mkdir()
                    except FileExistsError as exc:
                        raise ReshardError(f"manifest path conflicts with a directory: {destination}") from exc
                    except OSError as exc:
                        raise ReshardError(f"cannot create directory {destination}: {exc}") from exc
                    continue

                size = record.get("size")
                first_chunk = record.get("first_chunk")
                chunk_count = record.get("chunk_count")
                if (
                    isinstance(size, bool)
                    or not isinstance(size, int)
                    or size < 0
                    or isinstance(chunk_count, bool)
                    or not isinstance(chunk_count, int)
                    or chunk_count < 0
                ):
                    raise ReshardError("manifest contains an invalid file size or chunk count")
                expected_chunk_count = (size + MAX_FILE_SIZE - 1) // MAX_FILE_SIZE
                if chunk_count != expected_chunk_count:
                    raise ReshardError("manifest chunk count does not match file size")
                if chunk_count:
                    if (
                        isinstance(first_chunk, bool)
                        or not isinstance(first_chunk, int)
                        or first_chunk != next_chunk
                        or first_chunk < 0
                    ):
                        raise ReshardError("manifest payload chunks are out of order")
                elif first_chunk is not None:
                    raise ReshardError("empty file has an unexpected first chunk")

                if destination.exists():
                    raise ReshardError(f"manifest path conflicts with an existing path: {destination}")
                _copy_restored_file(
                    payload,
                    destination,
                    size,
                    first_chunk if isinstance(first_chunk, int) else None,
                    chunk_count,
                    total_chunks if total_chunks is not None else 0,
                )
                next_chunk += chunk_count
        finally:
            handle.close()

    if header is None or total_chunks is None:
        raise ReshardError("manifest does not contain a header")
    if next_chunk != total_chunks:
        raise ReshardError("manifest does not reference every payload chunk")


def decompress_directory(resharded_dir: str | os.PathLike[str]) -> None:
    root_argument = Path(resharded_dir)
    if root_argument.is_symlink():
        raise ReshardError("resharded directory must not be a symbolic link")
    try:
        root = root_argument.resolve(strict=True)
    except OSError as exc:
        raise ReshardError(f"cannot resolve resharded directory {resharded_dir}: {exc}") from exc
    if not root.is_dir():
        raise ReshardError(f"resharded path is not a directory: {resharded_dir}")

    manifest, payload = validate_resharded_layout(root)
    try:
        temporary = Path(
            tempfile.mkdtemp(prefix=f".{root.name}.restore-", dir=str(root.parent))
        )
    except OSError as exc:
        raise ReshardError(f"cannot create restoration directory: {exc}") from exc

    keep_temporary = True
    try:
        _reconstruct_into(root, manifest, payload, temporary)

        try:
            old_entries = list(root.iterdir())
        except OSError as exc:
            raise ReshardError(f"cannot read resharded directory before replacement: {exc}") from exc
        for entry in old_entries:
            if entry.is_dir() and not entry.is_symlink():
                shutil.rmtree(entry)
            else:
                entry.unlink()
        for entry in temporary.iterdir():
            os.replace(entry, root / entry.name)
        temporary.rmdir()
        keep_temporary = False
    finally:
        if keep_temporary:
            shutil.rmtree(temporary, ignore_errors=True)

